(37149, 'Joshua 23:12', 'Joshua', 23, 12, 'که چېرې تاسو بې وفایي وکړئ او د هغو قومونو سره یوځای شئ چې تر اوسه پورې ستاسو په منځ کې پاتې دي او د هغوی سره ودونه وکړئ،', 'که چېرې تاسو بې وفایی وکری او د هغو قومونو سره یوجای شی چې تر اوسه پورې ستاسو په منج کې پاتې دی او د هغوی سره ودونه وکری،', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(37150, 'Joshua 23:13', 'Joshua', 23, 13, 'نو بیا باور ولرئ چې څښتن خدای به نور دا قومونه ستاسو له مخې څخه لېرې نه کړي، بلکې هغوی به ستاسو دپاره د دام یا د لومې په شان خطرناک شي او ستاسو د شاګانو دپاره به د قمچینې په شان شي او ستاسو په سترګو کې به د اغزیو په شان شي. او دا به تر هغه وخته پورې دوام ومومي، ترڅو ستاسو څخه هېڅوک په دې ښې ځمکه کې چې خپل څښتن خدای درته درکړې ده پاتې نه شي.', 'نو بیا باور ولری چې چشتن خدای به نور دا قومونه ستاسو له مخې چخه لېرې نه کری، بلکې هغوی به ستاسو دپاره د دام یا د لومې په شان خطرناک شی او ستاسو د شاګانو دپاره به د قمچینې په شان شی او ستاسو په سترګو کې به د اغزیو په شان شی. او دا به تر هغه وخته پورې دوام ومومی، ترچو ستاسو چخه هېچوک په دې شې جمکه کې چې خپل چشتن خدای درته درکرې ده پاتې نه شی.', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(37151, 'Joshua 23:14', 'Joshua', 23, 14, 'اوس زما د مړینې وخت رارسېدلی دی. تاسو هر یو په خپل زړه کې پوهېږئ چې ستاسو څښتن خدای تاسو ته هغه ټول ښه شیان درکړي دي چې وعده یې کړې وه. هره وعده چې هغه کړې ده، هغه پوره شوې ده او یوه وعده یې هم ماته شوې نه ده.', 'اوس زما د مرینې وخت رارسېدلی دی. تاسو هر یو په خپل زره کې پوهېزی چې ستاسو چشتن خدای تاسو ته هغه تول شه شیان درکری دی چې وعده یې کرې وه. هره وعده چې هغه کرې ده، هغه پوره شوې ده او یوه وعده یې هم ماته شوې نه ده.', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(37152, 'Joshua 23:15', 'Joshua', 23, 15, 'خو لکه څنګه چې زمونږ څښتن خدای ستاسو سره د ټولو ښو شیانو وعده کړې ده او هغه یې سرته رسولې ده، نو هماغسې هغه به په تاسو باندې ټولې بدۍ هم راولي، ترڅو تاسو د دې ښې ځمکې څخه چې هغه تاسو ته درکړې ده، ورک کړي.', 'خو لکه چنګه چې زمونز چشتن خدای ستاسو سره د تولو شو شیانو وعده کرې ده او هغه یې سرته رسولې ده، نو هماغسې هغه به په تاسو باندې تولې بدی هم راولی، ترچو تاسو د دې شې جمکې چخه چې هغه تاسو ته درکرې ده، ورک کری.', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(37153, 'Joshua 23:16', 'Joshua', 23, 16, 'که چېرې تاسو هغه لوظ مات کړئ چې د هغه حکم یې په تاسو باندې کړی دی او د نورو خدایانو خدمت او عبادت وکړئ، نو بیا به هغه په قهر شي او تاسو ته به سزا درکړي او تاسو به زر د هغې ځمکې څخه ورک شئ چې زمونږ څښتن خدای تاسو ته درکړې ده.»', 'که چېرې تاسو هغه لوظ مات کری چې د هغه حکم یې په تاسو باندې کری دی او د نورو خدایانو خدمت او عبادت وکری، نو بیا به هغه په قهر شی او تاسو ته به سزا درکری او تاسو به زر د هغې جمکې چخه ورک شی چې زمونز چشتن خدای تاسو ته درکرې ده.»', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
